      "methods": [
        "Test"
      ],
      "rationale": "The requirement defines the OBU's operational behavior (treating start as temporary EOA and calculating SvL) before mode switching, which is verified by observing the speed limits and EOA status during the transition."
    },
    {
      "requirement_id": "ETC-109",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement specifies a data update mechanism (replacement) when receiving duplicate identity information, which is verified by sending sequential LX messages and checking the stored data."
    }
  ]
}

