    },
    {
      "requirement_id": "KDH-105",
      "methods": [
        "Test"
      ],
      "rationale": "Yetkisiz erişim, değişiklik veya silme girişimlerinin engellenmesi ve uyarı mekanizmasının çalışmasının, saldırı senaryoları simüle edilerek test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-106",
      "methods": [
