      ],
      "rationale": "Hassas işlemler öncesi tazelik süresi dolan oturumlarda yeniden kimlik doğrulama zorunluluğunun, sistem üzerinde işlem denemeleriyle test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-108",
      "methods": [
        "Test",
        "İnceleme"
      ],
      "rationale": "İletişim güvenliğinin, ağ trafiğinin yakalanarak test edilmesi ve şifreleme yapılandırmasının incelenmesiyle doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-109",
      "methods": [
        "Test"
      ],
      "rationale": "Geçersiz ve zararlı girdilerin sistemin reddetmesinin, çeşitli hata senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-110",
      "methods": [
        "Test"
      ],
      "rationale": "Hata mesajlarının kullanıcıya gösterilen genel hali ile yetkili personele gösterilen detaylı halinin, farklı yetki seviyeleriyle test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-111",
      "methods": [
        "Test"
      ],
      "rationale": "Oturum sonu uyarısı, taslak kaydetme ve veri kaybı olmadan devam etme akışının, kullanıcı senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-112",
      "methods": [
        "Test",
        "İnceleme"
      ],
      "rationale": "CAPTCHA kullanılmamasının kod incelemesiyle, bot eşiği aşımında etkileşimsiz kanıt ve nesne tanıma sorgusunun ise testle doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-113",
      "methods": [
        "Test"
      ],
      "rationale": "Ödeme sonucunun yalnızca imzalı bildirimle kabul edilmesi ve belirsiz durumların bekleme süresince sorgulanmasının, KÖA simülasyonlarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-114",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 altı veya eksik alanlı e-Devlet belirteçlerinde oturumun sınırlı kipte açılmasının, farklı token senaryolarıyla test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-115",
      "methods": [
        "Test"
      ],
      "rationale": "Parola geçerlilik süresinin yalnızca şirket temsilcilerine uygulanması, bildirimlerin ve ele geçirme kanıtında zorunlu değişikliğin test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-116",
      "methods": [
        "Test"
      ],
      "rationale": "TOTP kodlarının yalnızca geçerli ve bir önceki adımda kabul edilip, eski/ileri adımların reddedilmesinin ve tek kullanımlık olmasının test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-117",
      "methods": [
        "Test"
      ],
      "rationale": "Başarısız deneme eşiğinde doğrulayıcının devre dışı bırakılması, hesap kurtarma akışının ve sayaç sıfırlamanın test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-118",
      "methods": [
        "Test"
      ],
      "rationale": "Farklı AAL düzeylerinde hareketsizlik sonrası devam etme yöntemlerinin ve oturum sırrının silinmesinin, rol bazlı testlerle doğrulanması gerekir."
    },
    {
      "requirement_id": "KDH-119",
      "methods": [
        "Test"
      ],
      "rationale": "Eşzamanlı oturum sınırının aşılmasında en eski oturumun sonlandırılması, kullanıcı bildirimi ve SIEM iletiminin test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-120",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, içerik imzası ve boyut/sayı sınırlarının denetlenmesi ile ret mesajlarının, çeşitli dosya yükleme senaryolarıyla test edilmesi gerekir."
    }
  ]
}

