{
  "test_cases": [
    {
      "id": "TC-074-01",
      "title": "Adopt shortened MA when train is rear of Indication supervision limit",
      "covers": [
        "ETC-074"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in a mode where MA is active. The current MA has an Indication supervision limit (ISL) at position P_ISL. The train front end is at position P_Train such that P_Train < P_ISL.",
      "test_inputs": "RBC request to shorten MA to a new MA with ISL at P_NewISL. P_NewISL > P_Train.",
      "assumptions": "The new MA is valid and contains a mode profile and SH-area balise group list.",
      "steps": [
        {
          "no": 1,
          "action": "Send RBC request to shorten the MA to the new MA.",
          "expected": "OBU receives the request."
        },
        {
          "no": 2,
          "action": "OBU evaluates the position of the train front end relative to the proposed MA's Indication supervision limit.",
          "expected": "OBU determines that the train front end is in rear of the proposed MA's Indication supervision limit."
        },
        {
          "no": 3,
          "action": "OBU adopts the proposed shortened MA, including its mode profile and SH-area balise group list.",
          "expected": "The active MA in the OBU is updated to the new MA. The mode profile and SH-area balise group list are updated accordingly."
        },
        {
          "no": 4,
          "action": "OBU informs the RBC of its decision.",
          "expected": "OBU sends a message to the RBC indicating that the MA shortening request was accepted."
        }
      ]
    },
    {
      "id": "TC-074-02",
      "title": "Reject shortened MA when train is at or ahead of Indication supervision limit",
      "covers": [
        "ETC-074"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "OBU is in a mode where MA is active. The current MA has an Indication supervision limit (ISL) at position P_ISL. The train front end is at position P_Train such that P_Train >= P_ISL.",
      "test_inputs": "RBC request to shorten MA to a new MA with ISL at P_NewISL. P_NewISL <= P_Train.",
      "assumptions": "The new MA is valid and contains a mode profile and SH-area balise group list.",
      "steps": [
        {
          "no": 1,
          "action": "Send RBC request to shorten the MA to the new MA.",
          "expected": "OBU receives the request."
        },
        {
          "no": 2,
          "action": "OBU evaluates the position of the train front end relative to the proposed MA's Indication supervision limit.",
          "expected": "OBU determines that the train front end is not in rear of the proposed MA's Indication supervision limit."
        },
        {
          "no": 3,
          "action": "OBU rejects the request and keeps the previous MA, mode profile and list.",
          "expected": "The active MA in the OBU remains unchanged. The mode profile and SH-area balise group list remain unchanged."
        },
        {
          "no": 4,
          "action": "OBU informs the RBC of its decision.",
          "expected": "OBU sends a message to the RBC indicating that the MA shortening request was rejected."
        }
      ]
    },
    {
      "id": "TC-074-03",
      "title": "Boundary case: Train front end exactly at Indication supervision limit",
      "covers": [
        "ETC-074"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "OBU is in a mode where MA is active. The current MA has an Indication supervision limit (ISL) at position P_ISL. The train front end is at position P_Train such that P_Train == P_ISL.",
      "test_inputs": "RBC request to shorten MA to a new MA with ISL at P_NewISL. P_NewISL == P_Train.",
      "assumptions": "The new MA is valid and contains a mode profile and SH-area balise group list.",
      "steps": [
        {
          "no": 1,
          "action": "Send RBC request to shorten the MA to the new MA.",
          "expected": "OBU receives the request."
        },
        {
          "no": 2,
          "action": "OBU evaluates the position of the train front end relative to the proposed MA's Indication supervision limit.",
          "expected": "OBU determines that the train front end is not in rear of the proposed MA's Indication supervision limit (since it is at the limit, not rear of it)."
        },
        {
          "no": 3,
          "action": "OBU rejects the request and keeps the previous MA, mode profile and list.",
          "expected": "The active MA in the OBU remains unchanged. The mode profile and SH-area balise group list remain unchanged."
        },
        {
          "no": 4,
          "action": "OBU informs the RBC of its decision.",
          "expected": "OBU sends a message to the RBC indicating that the MA shortening request was rejected."
        }
      ]
    }
