{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Setting a new phone number triggers authenticator binding process",
      "covers": [
        "KDH-009"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with a pre-registered telephone number. The user is authenticated.",
      "test_inputs": "New valid telephone number.",
      "assumptions": "The system implements the NIST SP 800-63B-4 §4.1.2 binding process, which typically involves sending a one-time code to the new number and verifying it.",
      "steps": [
        {
          "no": 1,
          "action": "Navigate to the profile settings and select the option to change the pre-registered telephone number.",
          "expected": "The system initiates the authenticator binding process (e.g., prompts for a new number and sends a verification code to the new number)."
        },
        {
          "no": 2,
          "action": "Enter the new telephone number and submit the request.",
          "expected": "A one-time verification code is sent to the new telephone number."
        },
        {
          "no": 3,
          "action": "Enter the received verification code into the system.",
          "expected": "The system validates the code and successfully binds the new telephone number as the authenticator."
        },
        {
          "no": 4,
          "action": "Check the account profile details.",
          "expected": "The new telephone number is displayed as the current pre-registered number."
        }
      ]
    },
    {
      "id": "TC-2",
      "title": "Changing an existing phone number triggers authenticator binding process",
      "covers": [
        "KDH-009"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with a pre-registered telephone number. The user is authenticated.",
      "test_inputs": "New valid telephone number different from the current one.",
      "assumptions": "The system treats 'changing' the number identically to 'setting' a new one, requiring re-binding.",
      "steps": [
        {
          "no": 1,
          "action": "Navigate to the profile settings and select the option to change the pre-registered telephone number.",
          "expected": "The system initiates the authenticator binding process."
        },
        {
          "no": 2,
          "action": "Enter a new telephone number and submit the request.",
          "expected": "A one-time verification code is sent to the new telephone number."
        },
        {
          "no": 3,
          "action": "Enter the received verification code into the system.",
          "expected": "The system validates the code and updates the authenticator binding to the new number."
        },
        {
          "no": 4,
          "action": "Attempt to receive an SMS code for a subsequent action (e.g., password reset or login verification).",
          "expected": "The SMS code is sent to the new telephone number, not the old one."
        }
      ]
    },
    {
      "id": "TC-3",
      "title": "Failure to verify new phone number prevents binding",
      "covers": [
        "KDH-009"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with a pre-registered telephone number. The user is authenticated.",
      "test_inputs": "New valid telephone number, incorrect verification code.",
      "assumptions": "The binding process requires successful verification of the code sent to the new number.",
      "steps": [
        {
          "no": 1,
          "action": "Initiate the process to change the pre-registered telephone number to a new number.",
          "expected": "A verification code is sent to the new number."
        },
        {
          "no": 2,
          "action": "Enter an incorrect verification code.",
          "expected": "The system rejects the code and displays an error message."
        },
        {
          "no": 3,
          "action": "Check the account profile details.",
          "expected": "The pre-registered telephone number remains unchanged (still the old number)."
        }
      ]
    }
  ]
}

