      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists. An authenticator is bound to this account. The failed-attempt threshold defined in VBP SDD §14 has been reached, causing the authenticator to be disabled.",
      "test_inputs": "Valid company representative credentials, the disabled authenticator, and a valid re-binding token/confirmation.",
      "assumptions": "The specific value of the failed-attempt threshold is known from VBP SDD §14. The re-binding process follows NIST SP 800-63B-4 §4.1.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt to use the disabled authenticator for authentication without re-binding it.",
          "expected": "The system rejects the authentication attempt and indicates that the authenticator is disabled and requires re-binding."
        },
        {
          "no": 2,
          "action": "Initiate the re-binding process for the disabled authenticator to the company representative account.",
          "expected": "The system allows the re-binding process to start, as per NIST SP 800-63B-4 §4.1."
        },
        {
          "no": 3,
          "action": "Complete the re-binding process successfully.",
          "expected": "The authenticator is re-bound to the company representative account and its status changes to active/enabled."
        },
        {
          "no": 4,
          "action": "Attempt to use the re-bound authenticator for authentication.",
          "expected": "The system accepts the authenticator and allows the authentication to proceed."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Authenticator usage before re-binding is blocked",
      "covers": [
        "KDH-039"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists. An authenticator is bound to this account. The failed-attempt threshold defined in VBP SDD §14 has been reached, causing the authenticator to be disabled.",
      "test_inputs": "Valid company representative credentials, the disabled authenticator.",
      "assumptions": "The specific value of the failed-attempt threshold is known from VBP SDD §14.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt to use the disabled authenticator for authentication.",
          "expected": "The system rejects the authentication attempt."
        },
        {
          "no": 2,
          "action": "Check the system logs or user feedback for the reason of rejection.",
          "expected": "The system explicitly states that the authenticator is disabled due to reaching the failed-attempt threshold and must be re-bound before use."
        }
      ]
    }
  ]
}

