{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Failed sign-in response consistency for existing and non-existing users",
      "covers": [
        "KDH-055"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A valid user account exists in the system. A non-existing user identifier is known.",
      "test_inputs": "Valid user ID, invalid password. Non-existing user ID, invalid password.",
      "assumptions": "The system allows sign-in attempts with any user identifier format.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt sign-in with a valid user ID and an incorrect password.",
          "expected": "The system returns a generic error message (e.g., 'Invalid credentials') and an HTTP status code (e.g., 401 or 200 with error body) that does not indicate the user exists."
        },
        {
          "no": 2,
          "action": "Attempt sign-in with a non-existing user ID and an incorrect password.",
          "expected": "The system returns the exact same generic error message and HTTP status code as in step 1."
        },
        {
          "no": 3,
          "action": "Measure the response time for the sign-in attempt with the valid user ID.",
          "expected": "The response time is statistically indistinguishable from the response time of the non-existing user attempt (within a small margin of error, e.g., < 100ms difference)."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Failed registration response consistency for existing and non-existing email addresses",
      "covers": [
        "KDH-055"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "An email address is already registered in the system. A new, unregistered email address is available.",
      "test_inputs": "Existing email address, valid registration data. New email address, valid registration data.",
      "assumptions": "The registration process validates email uniqueness.",
      "steps": [
        {
          "no": 1,
          "action": "Submit a registration request with an already registered email address.",
          "expected": "The system returns a generic error message (e.g., 'Registration failed' or 'Please check your email') and an HTTP status code that does not explicitly state the email is already taken."
        },
        {
          "no": 2,
          "action": "Submit a registration request with a new, unregistered email address.",
          "expected": "The system returns the exact same generic error message and HTTP status code as in step 1 (or a success message that does not reveal prior state if the flow is identical, but typically both should be indistinguishable if the requirement implies preventing deduction from *failed* responses; if success is different, the failure case for existing email must not be distinguishable from a generic failure). *Correction based on strict interpretation*: If the requirement is about *failed* responses, we compare the failure of an existing email vs a failure of a new email (e.g., invalid data). However, usually, this test compares the response for 'email exists' vs 'email does not exist'. Let's assume the test compares the response when the email is already taken (a failure state) vs a generic failure or the response for a new email if the system treats both as 'processing'. To be safe, we compare the response for an existing email (failure) with a response for a new email that fails for another reason (e.g., invalid format) or simply ensure the 'email exists' error is not distinct. Let's refine: The requirement says 'prevent valid users from being deduced from... registration... responses'. This implies the response for an existing email should not be different from a response for a non-existing email in a way that reveals existence. Often, systems send a 'check your email' for both. Let's test that."
        },
        {
          "no": 3,
          "action": "Measure the response time for the registration attempt with the existing email address.",
          "expected": "The response time is statistically indistinguishable from the response time of the new email attempt."
        }
      ]
    },
